//! Canonicalisation vectors generated by the real CryptoEngine.

use pg_crypto::canonical::{canonicalize, CanonicalizationInput, CanonicalizationMode};
use serde::Deserialize;
use serde_json::{Map, Value};

const CANONICAL: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../tests/golden-vectors/canonical.json"
));

#[derive(Deserialize)]
struct File {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    id: String,
    mode: String,
    fields: Value,
    included_fields: Option<Vec<String>>,
    excluded_fields: Option<Vec<String>>,
    template_string: Option<String>,
    value_separator: Option<String>,
    expected: String,
}

#[test]
fn canonicalisation_matches_typescript() {
    let file: File = serde_json::from_str(CANONICAL).expect("canonical vectors");
    assert_eq!(file.cases.len(), 17);
    for case in file.cases {
        let mode = CanonicalizationMode::parse(&case.mode).expect("mode");
        let input = CanonicalizationInput {
            fields: case.fields.as_object().cloned().unwrap_or_else(Map::new),
            raw_body: None,
            timestamp: None,
            included_fields: case.included_fields,
            excluded_fields: case.excluded_fields,
            template_string: case.template_string,
            value_separator: case.value_separator,
        };
        assert_eq!(
            canonicalize(mode, &input).expect("canonicalise"),
            case.expected,
            "{}",
            case.id
        );
    }
}

#[test]
fn integer_like_keys_are_enumerated_numerically_in_json() {
    let mut fields = Map::new();
    fields.insert("0".to_owned(), Value::String("zero".to_owned()));
    fields.insert("2".to_owned(), Value::String("two".to_owned()));
    fields.insert("10".to_owned(), Value::String("ten".to_owned()));
    fields.insert("b".to_owned(), Value::from(1));
    let input = CanonicalizationInput {
        fields,
        ..CanonicalizationInput::default()
    };
    assert_eq!(
        canonicalize(CanonicalizationMode::JsonCanonical, &input).expect("json"),
        r#"{"0":"zero","2":"two","10":"ten","b":1}"#
    );
}
